// Turn each starred email into a Markdown note for your Obsidian vault.
// Field names vary a little between Gmail node versions, so we read defensively.
const cfg = $('⚙️ Your settings').first().json;
const pad = (n) => String(n).padStart(2, '0');

// Strip the characters Obsidian and common filesystems reject in a filename.
const slug = (s) => String(s || 'note')
  .replace(/[\\/:*?"<>|#^\[\]]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 80) || 'note';

const esc = (s) => String(s == null ? '' : s).replaceAll('"', "'");

// The Gmail node returns "from" as an object ({ text, value: [{ name, address }] }); make it a string.
const who = (f) => {
  if (!f) return '';
  if (typeof f === 'string') return f;
  if (f.text) return f.text;
  if (Array.isArray(f.value)) return f.value.map(v => (v.name ? `${v.name} <${v.address}>` : v.address)).join(', ');
  return String(f);
};

// Many emails are HTML-only (no plain-text part): turn the HTML into readable text.
const stripHtml = (h) => String(h || '')
  .replace(/<style[\s\S]*?<\/style>|<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>|<\/p>|<\/div>|<\/tr>|<\/li>|<\/h[1-6]>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"')
  .replace(/[ \t]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();

const notes = [];

for (const item of $input.all()) {
  const m = item.json;
  const subject = m.subject || m.Subject || '(no subject)';
  const from = who(m.from || m.From || m.sender);
  const rawDate = m.date || m.Date || m.internalDate || '';
  const body = (m.text && String(m.text).trim()) || m.textPlain || stripHtml(m.html) || m.snippet || '';

  // Build a safe date prefix; fall back to today if the header is unparseable.
  let d = new Date(rawDate);
  if (isNaN(d.getTime())) d = new Date();
  const stamp = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;

  // A short id suffix keeps two emails with the same subject and date from overwriting each other.
  const filename = `${stamp} ${slug(subject)} ${String(m.id || '').slice(-6)}.md`;

  const frontmatter = [
    '---',
    `title: "${esc(subject)}"`,
    `from: "${esc(from)}"`,
    `date: ${stamp}`,
    'source: gmail',
    `tags: [${cfg.noteTag || 'email'}]`,
    '---',
    '',
  ].join('\n');

  const markdown = `${frontmatter}# ${subject}\n\n**From:** ${from}  \n**Date:** ${stamp}\n\n${body}\n`;

  notes.push({
    json: {
      message_id: m.id,
      filename,
      markdown,
    },
  });
}

return notes;
